1	import 'package:dio/dio.dart';
2	
3	import 'dio_error_code.dart';
4	import 'header_interceptor.dart';
5	
6	/// AD-4 — the one place retry policy lives. Retries only the 6 server
7	/// `retryable:true` codes (`error-taxonomy.md`); every other failure
8	/// (including the local `MalformedResponse`) surfaces once, unretried.
9	///
10	/// Design note (docs/input is silent on the schedule): fixed 500ms delay,
11	/// max 2 retries.
12	class RetryInterceptor extends Interceptor {
13	  RetryInterceptor(this._dio);
14	
15	  final Dio _dio;
16	
17	  /// The 6 server `retryable:true` codes — the only codes this interceptor
18	  /// ever retries.
19	  static const Set<String> retryableCodes = {
20	    'NETWORK_TIMEOUT',
21	    'NETWORK_OFFLINE',
22	    'PII_CHECK_FAILED',
23	    'EMBEDDING_FAILED',
24	    'AI_GENERATION_TIMEOUT',
25	    'RATE_LIMITED',
26	  };
27	
28	  /// Non-idempotent POSTs with no client-supplied idempotency key — a
29	  /// transparent retry here would silently resend the identical request
30	  /// (the same chat message content, or a second session-create) rather
31	  /// than surfacing the failure once to the caller. `dioErrorCodeOf` can
32	  /// return a retryable code for these from `DioException.type` alone
33	  /// (`NETWORK_TIMEOUT`/`NETWORK_OFFLINE`) even before any response body
34	  /// exists to carry the real `{code,message}`, so excluding by function
35	  /// name here is the only place this can be enforced.
36	  ///
37	  /// spec-7-1 — `export-summary-create` joins this set for the same
38	  /// reason: it enqueues a brand-new export job with no client-supplied
39	  /// idempotency key, so a transparent retry risks creating a second,
40	  /// duplicate job rather than resurfacing the original failure once.
41	  static const Set<String> neverRetriedFunctions = {
42	    'chat-messages-send',
43	    'chat-messages-retry',
44	    'chat-sessions-create',
45	    'export-summary-create',
46	  };
47	
48	  static const int maxRetries = 2;
49	  static const Duration retryDelay = Duration(milliseconds: 500);
50	
51	  static const _attemptKey = 'cerne_retry_attempt';
52	
53	  @override
54	  void onError(DioException err, ErrorInterceptorHandler handler) async {
55	    final attempt = attemptOf(err);
56	
57	    if (shouldRetry(err, attempt)) {
58	      await Future<void>.delayed(retryDelay);
59	      final options = err.requestOptions;
60	      options.extra[_attemptKey] = attempt + 1;
61	      try {
62	        final response = await _dio.fetch<dynamic>(options);
63	        handler.resolve(response);
64	      } on DioException catch (retryError) {
65	        handler.next(retryError);
66	      } catch (retryError) {
67	        // Any non-DioException thrown by the retried fetch must still reach
68	        // the caller through `handler`, never escape unhandled (RNF09).
69	        handler.next(
70	          DioException(
71	            requestOptions: options,
72	            error: retryError,
73	            type: DioExceptionType.unknown,
74	          ),
75	        );
76	      }
77	      return;
78	    }
79	
80	    handler.next(err);
81	  }
82	
83	  /// How many retries have already been attempted for this request.
84	  static int attemptOf(DioException err) =>
85	      (err.requestOptions.extra[_attemptKey] as int?) ?? 0;
86	
87	  /// The backend error `code` for [err] — delegates to the shared
88	  /// [dioErrorCodeOf] (also used by `ApiClient`) so a client-side timeout or
89	  /// a cancelled request is never misread as `NETWORK_OFFLINE` here.
90	  static String? errorCodeOf(DioException err) => dioErrorCodeOf(err);
91	
92	  /// Pure decision function, independently testable: retry only if the
93	  /// error's code is one of the 6 allowlisted codes, the max-retries
94	  /// budget isn't exhausted yet, and the request isn't one of the
95	  /// [neverRetriedFunctions].
96	  static bool shouldRetry(DioException err, int attempt) {
97	    final code = errorCodeOf(err);
98	    if (code == null ||
99	        !retryableCodes.contains(code) ||
100	        attempt >= maxRetries) {
101	      return false;
102	    }
103	    final function = HeaderInterceptor.functionNameOf(err.requestOptions.path);
104	    return !neverRetriedFunctions.contains(function);
105	  }
106	}
