15	/// Maps the DTO to the domain entity and saves both the access token and
16	/// the refresh token (Story 1.4) *before* returning `right(...)`.
17	class AuthRepositoryImpl implements AuthRepository {
18	  AuthRepositoryImpl({
19	    required AuthRemoteDataSource remoteDataSource,
20	    required AccessTokenProvider accessTokenProvider,
21	  }) : _remoteDataSource = remoteDataSource,
22	       _accessTokenProvider = accessTokenProvider;
23	
24	  final AuthRemoteDataSource _remoteDataSource;
25	  final AccessTokenProvider _accessTokenProvider;
26	
27	  @override
28	  Future<Either<Failure, AuthenticatedUser>> signUp({
29	    required String email,
30	    required String password,
31	  }) => _authenticate(
32	    () => _remoteDataSource.signUp(email: email, password: password),
33	  );
34	
35	  @override
36	  Future<Either<Failure, AuthenticatedUser>> logIn({
37	    required String email,
38	    required String password,
39	  }) => _authenticate(
40	    () => _remoteDataSource.logIn(email: email, password: password),
41	  );
