43	  Future<Either<Failure, AuthenticatedUser>> _authenticate(
44	    Future<Either<Failure, AuthResponseDto>> Function() call,
45	  ) async {
46	    final result = await call();
47	    return result.match((failure) async => left(failure), (dto) async {
48	      // A thrown platform exception (secure-storage channel failure, disk
49	      // issue, ...) must never escape unmapped (RNF09/AD-2) — if the token
50	      // can't be persisted, the call as a whole must surface as a Failure
51	      // rather than leave the caller awaiting forever. Deliberately reuses
52	      // `malformedResponse` (the only local-only variant in the closed,
53	      // exactly-14-subtype `Failure` hierarchy, AD-3) rather than adding a
54	      // new subtype just for this — it mislabels a local persistence
55	      // failure as a response-shape failure, but a dedicated subtype
56	      // isn't available without widening the closed hierarchy.
57	      try {
58	        await _accessTokenProvider.saveSession(
59	          accessToken: dto.data.session.accessToken,
60	          refreshToken: dto.data.session.refreshToken,
61	        );
62	      } catch (error) {
63	        return left(Failure.malformedResponse(message: error.toString()));
64	      }
65	      return right(
66	        AuthenticatedUser(id: dto.data.user.id, email: dto.data.user.email),
67	      );
68	    });
69	  }
70	}
