67	/// Stories 1.3-1.5 built this on top of is replaced by the one real
68	/// `go_router` (`core/navigation/app_router.dart`) plus its
69	/// `ExpiryOverlayHost` wrapper — [restoreSession] still fires once at boot
70	/// here (unchanged from Story 1.4), but every screen transition and the
71	/// expiry overlay's own "Entrar novamente" now go through that router
72	/// instead of an imperative `Navigator`.
73	class CerneApp extends StatefulWidget {
74	  const CerneApp({super.key});
75	
76	  @override
77	  State<CerneApp> createState() => _CerneAppState();
78	}
79	
80	class _CerneAppState extends State<CerneApp> {
81	  late final SessionRepository _sessionRepository;
82	  late final VaultRepository _vaultRepository;
83	  late final AccountSettingsRepository _accountSettingsRepository;
84	  late final GoRouter _router;
85	
86	  // Created here (not left for `GoRouter` to generate internally) and
87	  // passed to both `buildAppRouter` and `ExpiryOverlayHost` below, so the
88	  // latter can reach the Navigator's own `BuildContext` through this
89	  // public, documented key instead of reaching into `GoRouter`'s internal
90	  // `routerDelegate`.
91	  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>(
92	    debugLabel: 'root',
93	  );
