95	  @override
96	  void initState() {
97	    super.initState();
98	    _sessionRepository = sl<SessionRepository>();
99	    _vaultRepository = sl<VaultRepository>();
100	    _accountSettingsRepository = sl<AccountSettingsRepository>();
101	    _router = buildAppRouter(
102	      vaultRepository: _vaultRepository,
103	      sessionRepository: _sessionRepository,
104	      accountSettingsRepository: _accountSettingsRepository,
105	      navigatorKey: _navigatorKey,
106	    );
107	    // Fire-and-forget: the outcome reaches the UI through
108	    // `SessionRepository.currentStatus`/`statusStream` (which the router's
109	    // `redirect`/`refreshListenable` already watch), not through this
110	    // call's return value. `restoreSession()` already maps every internal
111	    // failure to `Left`/an `unauthenticated` emission and never throws.
112	    // This `catchError` is NOT a UI recovery path — its handler's return
113	    // value is discarded by `unawaited` and never reaches `statusStream`.
114	    // It exists purely so a future regression that broke the "never
115	    // throws" contract above would surface as a logged message instead of
116	    // an unhandled zone exception.
