124	    // `refreshListenable` already watches), never through this call's
125	    // return value, and a failure leaves `currentBiometricEnabled`
126	    // unchanged (I/O matrix) rather than surfacing anywhere.
127	    unawaited(
128	      _accountSettingsRepository.fetchBiometricEnabled().catchError(
