140	  // `catchError`'s handler must still complete the Future with a value of
141	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
142	  // handler would try to complete it with `null`, which isn't assignable
143	  // to that non-nullable type and would itself throw.
144	  static Either<Failure, Unit> _asUnauthenticated(
145	    Object error,
146	    StackTrace stackTrace,
147	  ) {
148	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
149	    return left(Failure.malformedResponse(message: error.toString()));
150	  }
151	
152	  @override
153	  Widget build(BuildContext context) {
154	    return MaterialApp.router(
155	      debugShowCheckedModeBanner: false,
156	      // Review finding (spec-7-1): every hand-written string in the app is
157	      // already PT-BR, but `showDateRangePicker` (the export period
158	      // picker) is Flutter's own built-in widget — without these, it falls
159	      // back to US English ("CANCEL"/"SELECT RANGE") on an otherwise
160	      // all-Portuguese screen.
161	      locale: const Locale('pt', 'BR'),
162	      localizationsDelegates: const [
163	        GlobalMaterialLocalizations.delegate,
164	        GlobalWidgetsLocalizations.delegate,
165	        GlobalCupertinoLocalizations.delegate,
166	      ],
167	      supportedLocales: const [Locale('pt', 'BR')],
168	      routerConfig: _router,
169	      builder: (context, child) => ExpiryOverlayHost(
170	        sessionRepository: _sessionRepository,
171	        router: _router,
172	        navigatorKey: _navigatorKey,
173	        child: child!,
174	      ),
175	    );
176	  }
177	}
